"""Files a project needs once to run UAC tests with evidence. Never overwrites existing files."""

from __future__ import annotations

import json
from pathlib import Path

from . import attacks, store

PLAYWRIGHT_CONFIG = """\
// Generated by qa-review for acceptance-criteria (UAC) tests. Safe to edit.
import {{ defineConfig }} from '@playwright/test';

export default defineConfig({{
  testDir: './{tests_dir}',
  outputDir: process.env.QA_REVIEW_UAC_ARTIFACTS || './.qa-review/uac/artifacts',
  fullyParallel: true,
  retries: 0,
  reporter: [
    ['json', {{ outputFile: process.env.QA_REVIEW_UAC_JSON || './.qa-review/uac/results.json' }}],
    ['line'],
  ],
  use: {{
    baseURL: process.env.BASE_URL,                       // the host given to `uac_run` / --host
    channel: process.env.QA_REVIEW_BROWSER_CHANNEL || undefined,   // e.g. 'chrome' to use installed Chrome
    screenshot: 'on',                                    // final screenshot of every UI test = evidence
    trace: 'retain-on-failure',
    video: (process.env.QA_REVIEW_VIDEO as 'on' | 'off' | 'retain-on-failure') || 'retain-on-failure',  // needs ffmpeg
    extraHTTPHeaders: process.env.QA_REVIEW_API_TOKEN
      ? {{ Authorization: `Bearer ${{process.env.QA_REVIEW_API_TOKEN}}` }} : undefined,
  }},
}});
"""

EVIDENCE = """\
// Evidence helpers for UAC tests (generated by qa-review). Everything attached here shows up,
// per UAC, in the qa-review report.
import { test, type Page, type APIRequestContext, type APIResponse } from '@playwright/test';

const SECRET = /authorization|cookie|token|secret|password|api[-_]?key/i;
const hide = (h: Record<string, string> = {}) =>
  Object.fromEntries(Object.entries(h).map(([k, v]) => [k, SECRET.test(k) ? '[hidden]' : v]));

/** Screenshot of the page right now, labelled (use it after each visible Then). */
export async function shot(page: Page, label: string): Promise<void> {
  await test.info().attach(`shot: ${label}`, { body: await page.screenshot({ fullPage: true }), contentType: 'image/png' });
}

/** Free-text evidence: ids created, values read, anything a reviewer should see. */
export async function note(text: string): Promise<void> {
  await test.info().attach('note', { body: text, contentType: 'text/plain' });
}

type Method = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

/** An HTTP call that records request and response (secrets hidden) as evidence. */
export async function apiCall(request: APIRequestContext, method: Method, url: string, data?: unknown,
                              options: { headers?: Record<string, string> } = {}): Promise<APIResponse> {
  const res = await request.fetch(url, { method, data, headers: options.headers });
  const text = await res.text();
  let body: unknown = text;
  try { body = JSON.parse(text); } catch { /* not JSON: keep the text */ }
  await test.info().attach(`api: ${method} ${url}`, {
    contentType: 'application/json',
    body: JSON.stringify({
      request: { method, url: res.url(), headers: hide(options.headers), data: data ?? null },
      response: { status: res.status(), headers: hide(res.headers()), body },
    }, null, 2),
  });
  return res;
}
"""


ATTACKS_TS = """\
// Attack helpers for @break UACs (generated by qa-review from its own payload catalogue). Safe to edit.
import {{ expect, type Page, type APIRequestContext, type APIResponse }} from '@playwright/test';
import {{ note }} from './evidence';

export const PAYLOADS = {{ ...{payloads}, long: 'a'.repeat(10_000) }} as const;

const LEAKS = {leaks}.map((p) => new RegExp(p, 'i'));

/** The response must not show internals (stack traces, SQL errors, file paths, debug pages). */
export async function expectNoLeak(res: APIResponse): Promise<void> {{
  const body = await res.text();
  const leak = LEAKS.find((rx) => rx.test(body));
  if (leak) await note(`leak detected: ${{body.match(leak)?.[0]}}`);
  expect(leak, `response leaks internals (${{res.status()}} ${{res.url()}})`).toBeUndefined();
}}

/** Hostile input must be rejected cleanly: a 4xx (or the exact status given), never a 5xx or a 2xx. */
export async function expectSafeError(res: APIResponse, opts: {{ status?: number }} = {{}}): Promise<void> {{
  const status = res.status();
  if (opts.status !== undefined) expect(status, `expected ${{opts.status}} from ${{res.url()}}`).toBe(opts.status);
  else {{
    expect(status, `server error on hostile input: ${{res.url()}}`).toBeLessThan(500);
    expect(status, `hostile input was accepted (${{status}}): ${{res.url()}}`).toBeGreaterThanOrEqual(400);
  }}
  await expectNoLeak(res);
}}

/** Run the same action n times at once (double submit, races). Returns every result. */
export async function inParallel<T>(n: number, action: (i: number) => Promise<T>): Promise<T[]> {{
  return Promise.all(Array.from({{ length: n }}, (_, i) => action(i)));
}}

/** The JSON (or text) a GET returns now, to compare state before and after an attack. */
export async function snapshot(request: APIRequestContext, url: string): Promise<unknown> {{
  const res = await request.get(url);
  const text = await res.text();
  try {{ return JSON.parse(text); }} catch {{ return text; }}
}}

/** Make the API calls matching `pattern` fail with `status` (UI resilience). */
export async function failApi(page: Page, pattern: string, status = 500): Promise<void> {{
  await page.route(pattern, (route) => route.fulfill({{ status, body: JSON.stringify({{ error: 'qa-review injected failure' }}),
    contentType: 'application/json' }}));
}}

/** Cut the network (UI resilience). */
export async function goOffline(page: Page): Promise<void> {{
  await page.context().setOffline(true);
}}
"""


def _attacks_ts() -> str:
    payloads = {"injection": attacks.PAYLOADS["injection"], "unicode": attacks.PAYLOADS["unicode"],
                "numbers": [n for n in attacks.PAYLOADS["numbers"] if abs(n) < 1e300],
                "wrongTypes": attacks.PAYLOADS["wrong_types"], "strings": ["", " "]}
    leaks = [p.replace("(?i)", "") for p in attacks.LEAK_PATTERNS]
    return ATTACKS_TS.format(payloads=json.dumps(payloads, ensure_ascii=False, indent=2),
                             leaks=json.dumps(leaks, indent=2))


def ensure(root: Path) -> list[str]:
    """Create the Playwright config and the evidence helpers if missing. Returns the files created."""
    st = store.settings(root)
    created = []
    targets = {
        Path(root) / st.playwright_config: PLAYWRIGHT_CONFIG.format(tests_dir=st.tests_dir.strip("/")),
        Path(root) / st.tests_dir / "evidence.ts": EVIDENCE,
        Path(root) / st.tests_dir / "attacks.ts": _attacks_ts(),
    }
    for p, text in targets.items():
        if not p.exists():
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(text, encoding="utf-8")
            created.append(str(p.relative_to(root)))
    return created
